/* New Leaf tool models and tool-use animations for the player's held tools.
 * Data is generated by asset_import_work/generate_tools.py and generate_tool_anims.py.
 * PC_TOOLS_NATIVE=1 keeps the GameCube tools; PC_TOOLS_GC_ANIM=1 keeps only the GameCube animations. */
#include "pc_platform.h"
#include "PR/mbi.h"
#include "libultra/libultra.h"
#include "libforest/gbi_extensions.h"
#include "c_keyframe.h"
#include <stdlib.h>
#include "pc_tools.c_inc"
#include "pc_tool_anims.c_inc"

/* Runs before main: the joint tables and animation records are plain data, patched once. */
__attribute__((constructor)) static void pc_tools_init(void) {
    if (getenv("PC_TOOLS_NATIVE") != NULL) {
        g_pc_nl_tools = 0;
        return;
    }
    pc_tool_patch_joints();
    if (getenv("PC_TOOLS_GC_ANIM") == NULL) pc_tool_patch_anims();
}

/* Called for every held-tool data pointer: swaps the static tool models (axe, shovel). */
void* pc_tool_item_data(void* native) {
    return pc_tool_static_dl((Gfx*)native);
}
